# 32_meta_fit.R: model comparison on the pH x productivity metacommunity (50 replicates, three dominance scenarios, orders 2, 3, 4, 5, 8, balanced vs random site combinations, four responses).
# Models (identical I-spline bases from the TRAINING sites, logit link, nonnegativity, matched penalties; interaction restricted to the focal predictor pH, productivity terms additive):
#   spread_only; additive (nonlinear position); same_<shrink>: pH spread coefficients interpolated by the pH position coordinate (current architecture, focal-restricted);
#   cross_<shrink>: pH spread coefficients interpolated by the PRODUCTIVITY position coordinate (same endpoint-interpolation architecture; experimental, implemented here only).
# Interaction shrinkage 5e-3 (empirical default) and 1e-6 (weak). Random site-level 70/30 split; training / test combinations drawn from training / test sites only. Run from final/ (ZG_LIB6 set).
source("revision_ident/30_meta_common.R"); NC <- as.integer(Sys.getenv("NCORES", "9")); NREP <- as.integer(Sys.getenv("NREP", "50")); ORDERS <- c(2, 3, 4, 5, 8); M_RAND <- 2400L; TRU <- read.csv("revision_ident/tables/meta_truth_surfaces.csv")
SPECS <- list(spread_only = list(type = "spread_only"), additive = list(type = "additive"), same = list(type = "interaction", focal = "X", from = "X"), cross = list(type = "interaction", focal = "X", from = "P"))
CFG <- data.frame(config = c("spread_only", "additive", "same_5e-03", "same_1e-06", "cross_5e-03", "cross_1e-06"), spec = c("spread_only", "additive", "same", "same", "cross", "cross"), stage = c("curvature", "curvature", "shrink", "weakshrink", "shrink", "weakshrink"), stringsAsFactors = FALSE)
TCELL <- function(k) { tp <- truth_profiles(k); tp }; TPK <- lapply(ORDERS, TCELL); names(TPK) <- ORDERS
did_from <- function(eta, meta, f = identity) { g <- function(m, h, Pm) mean(f(eta[abs(meta$m - m) < 1e-9 & abs(meta$h - h) < 1e-9 & abs(meta$Pm - Pm) < 1e-9])); sp <- function(m, Pm) g(m, .3, Pm) - g(m, .1, Pm); c(did_P = sp(.5, .8) - sp(.5, .2), did_X = sp(.65, .5) - sp(.35, .5), eff_lowP = sp(.5, .2), eff_highP = sp(.5, .8)) }
one <- function(job) { scn <- job$scn; rep <- job$rep; sd0 <- 50000L + 1000L * match(scn, MSCN) + rep; env <- make_sites(sd0); set.seed(sd0 + 1); cnt <- sample_counts(env, scn); stopifnot(all(rowSums(cnt) == N_TOT)); perm <- sample(nrow(env)); tr <- sort(perm[1:437]); te <- sort(perm[438:625]); out <- list(); surf <- list()
  for (k in ORDERS) for (arm in c("balanced", "random")) { sd1 <- sd0 * 10 + k; if (arm == "balanced") { A <- balanced_sites(env, tr, k, 20, sd1); B <- balanced_sites(env, te, k, 8, sd1 + 1); itr <- A$idx; ite <- B$idx; ncell <- length(unique(A$meta$cell)) } else { itr <- matrix(tr[sample_sets(length(tr), k, M_RAND, seed = sd1)], ncol = k); ite <- matrix(te[sample_sets(length(te), k, M_RAND, seed = sd1 + 1)], ncol = k); ncell <- NA }
    if (is.null(itr) || nrow(itr) < 100 || nrow(ite) < 50) next; rtr <- resp_all(cnt, itr); rte <- resp_all(cnt, ite); ltr <- matrix(match(itr, tr), ncol = k); lte <- matrix(match(ite, te), ncol = k); envtr <- env[tr, ]; envte <- env[te, ]; tpk <- TPK[[as.character(k)]]
    BX <- lapply(SPECS, function(sp) { btr <- build_X(envtr, ltr, sp); list(tr = btr, te = build_X(envte, lte, sp, btr), tp = build_X(tpk$env, tpk$idx, sp, btr)) }); ba_te <- BX$additive$te; tru <- TRU[TRU$scenario == scn & TRU$order == k, ]; tru <- tru[match(paste(tpk$meta$m, tpk$meta$h, tpk$meta$Pm, tpk$meta$arrangement), paste(tru$m, tru$h, tru$Pm, tru$arrangement)), ]
    for (rn in RESP) { ktr <- rtr$keep & is.finite(rtr[[rn]]); kte <- rte$keep & is.finite(rte[[rn]]); y_tr <- rtr[[rn]][ktr]; y_te <- rte[[rn]][kte]; w_tr <- if (rn == "incidence") rtr$trials_inc[ktr] else rep(1, sum(ktr)); w_te <- if (rn == "incidence") rte$trials_inc[kte] else rep(1, sum(kte)); mu0 <- sum(w_tr * y_tr) / sum(w_tr)
      tr_resp <- tru[[rn]]; tr_eta <- qlogis(pmin(pmax(tr_resp, 1e-6), 1 - 1e-6)); tdid <- did_from(tr_eta, tpk$meta); tdidr <- did_from(tr_resp, tpk$meta)
      for (ci in seq_len(nrow(CFG))) { cf <- CFG[ci, ]; bx <- BX[[cf$spec]]; svec <- STAGES[[cf$stage]]; if (cf$spec %in% c("spread_only", "additive")) svec[["interaction_shrink"]] <- 0
        r <- tryCatch({ btr <- bx$tr; sub <- btr; sub$X <- btr$X[ktr, , drop = FALSE]; P <- pen_matrix(btr, as.list(svec)); f <- fit_pkg(sub, y_tr, w_tr, P); co <- f$coef; Xte <- bx$te$X[kte, , drop = FALSE]; p <- plogis(drop(Xte %*% co[colnames(Xte)])); eta_tp <- pred_eta(bx$tp, co); sv <- svd(sweep(sub$X, 2, sqrt(colSums(sub$X^2)), "/"), nu = 0)$d
          ed <- did_from(eta_tp, tpk$meta); edr <- did_from(plogis(eta_tp), tpk$meta); sx <- if (cf$spec %in% c("same", "cross")) { dh <- co[paste0("X_f", 1:3, "_U")] - co[paste0("X_f", 1:3, "_L")]; Xu <- bx$te$X[, paste0("X_f", 1:3, "_U")]; sd(qr.resid(qr(ba_te$X), Xu %*% dh)) } else NA
          if (arm == "balanced" && rn == "relative" && k %in% c(2, 5)) surf[[length(surf) + 1]] <- data.frame(scenario = scn, replicate = rep, order = k, config = cf$config, tpk$meta, eta_est = eta_tp, eta_true = tr_eta, resp_est = plogis(eta_tp), resp_true = tr_resp)
          data.frame(scenario = scn, replicate = rep, order = k, arm = arm, response = rn, config = cf$config, model = cf$spec, n_train_sets = sum(ktr), n_test_sets = sum(kte), n_cells_filled = ncell, rank = qr(sub$X)$rank, n_parameters = ncol(sub$X), scaled_condition = max(sv) / min(sv), D2_test = d2_frac(y_te, p, w_te, mu0), D2_train = 1 - bdev(y_tr, plogis(drop(sub$X %*% co)), w_tr) / bdev(y_tr, rep(mu0, length(y_tr)), w_tr), converged = isTRUE(f$converged),
            rmse_link = sqrt(mean((eta_tp - tr_eta)^2)), rmse_resp = sqrt(mean((plogis(eta_tp) - tr_resp)^2)), est_link_did_P = ed[["did_P"]], true_link_did_P = tdid[["did_P"]], est_resp_did_P = edr[["did_P"]], true_resp_did_P = tdidr[["did_P"]], est_link_did_X = ed[["did_X"]], true_link_did_X = tdid[["did_X"]], est_resp_did_X = edr[["did_X"]], true_resp_did_X = tdidr[["did_X"]],
            est_link_effect_lowP = ed[["eff_lowP"]], est_link_effect_highP = ed[["eff_highP"]], true_link_effect_lowP = tdid[["eff_lowP"]], true_link_effect_highP = tdid[["eff_highP"]], est_resp_effect_lowP = edr[["eff_lowP"]], est_resp_effect_highP = edr[["eff_highP"]], true_resp_effect_lowP = tdidr[["eff_lowP"]], true_resp_effect_highP = tdidr[["eff_highP"]], outside_sd_est = sx) }, error = function(e) { message("ERR ", scn, " ", rep, " ", k, " ", arm, " ", rn, " ", cf$config, ": ", conditionMessage(e)); NULL }); if (!is.null(r)) out[[length(out) + 1]] <- r } } }
  list(r = bind_rows(out), s = bind_rows(surf)) }
jobs <- do.call(c, lapply(MSCN, function(s) lapply(seq_len(NREP), function(r) list(scn = s, rep = r)))); if (nzchar(Sys.getenv("ONLY"))) jobs <- jobs[as.integer(strsplit(Sys.getenv("ONLY"), ",")[[1]])]; t0 <- Sys.time(); RES <- mclapply(jobs, one, mc.cores = NC, mc.preschedule = FALSE); cat("elapsed", format(Sys.time() - t0), "bad", sum(!vapply(RES, is.list, TRUE)), "\n")
R <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$r)); S <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$s)); sfx <- if (nzchar(Sys.getenv("ONLY"))) "_test" else ""; write.csv(R, sprintf("revision_ident/tables/meta_fits%s.csv", sfx), row.names = FALSE); write.csv(S, sprintf("revision_ident/tables/meta_surfaces%s.csv", sfx), row.names = FALSE); cat("rows", nrow(R), nrow(S), "nonconverged", sum(!R$converged), "\n")
